     "summary": "据“市说新语”微信公众号9月16日消息，近期，我国深度参与国际标准化组织（ISO）、国际电工委员会（IEC）新材料领域标准化工作，推动国际标准立项、研制与发布。下一步，市场监管总局等部门将聚焦石墨烯、纳米材料、新型储能材料等方向，推动国内先进技术成果转化为国际标准，以高水平标准赋能新材料产业高质量发展，加快形成新质生产力。",
